    mustMentionIdentifiers: ['web-app-pod', 'api-service.staging', 'staging'],
  },

  'network-policy-deny': {
    name: 'NetworkPolicy Deny-All Egress',
    minFindings: 3,
    topFindingMustMatch: [
      /NetworkPolicy/i,
      /deny-all-egress/i,
      /egress/i,
      /payments-api/i,
    ],
    topFindingSeverity: ['high'],
    topFindingMinConfidence: 0.9,
    mustCiteEvidence: [
      /networkpolicies/i,
      /pods/i,
      /services/i,
      /logs/i,
    ],
    mustNotHallucinate: [
      /ImagePullBackOff/i,
      /CrashLoopBackOff/i,
      /missing.*secret/i,
    ],
    rootCauseMustMatch: [
      /networkpolicy|deny|egress|outbound/i,
      /payments-api|service|port 8443/i,
    ],
    mustMentionIdentifiers: ['api-client-pod', 'deny-all-egress', 'payments-api'],
  },

  'helm-release-failure': {
    name: 'Helm Release Failure (Failed Hook CrashLoop)',
    minFindings: 1,
    topFindingMustMatch: [
      /CrashLoopBackOff/i,
      /storefront-hook-pod/i,
      /hook/i,
    ],
    topFindingSeverity: ['critical'],
    topFindingMinConfidence: 0.95,
    mustCiteEvidence: [
      /pods/i,
      /events/i,
    ],
    mustNotHallucinate: [
      /ImagePullBackOff/i,
      /missing.*secret/i,
      /NetworkPolicy/i,
    ],
    rootCauseMustMatch: [
      /crashloop|backoff|restart/i,
      /migrate-hook|storefront-hook-pod/i,
    ],
    mustMentionIdentifiers: ['storefront-hook-pod', 'migrate-hook'],
  },

  'wrong-db-endpoint': {
    name: 'Wrong DB Endpoint (DNS Failure)',
    minFindings: 1,
    topFindingMustMatch: [
      /dns/i,
      /db\.internal/i,
      /database/i,
      /endpoint/i,
      /no such host/i,
      /not ready/i,
      /readiness/i,
    ],
    topFindingSeverity: ['critical', 'high'],
    topFindingMinConfidence: 0.7,
    mustCiteEvidence: [
      /logs|events|pods/i,
    ],
    mustNotHallucinate: [
      /ImagePullBackOff/i,
      /CrashLoopBackOff/i,
