  const analyzerFiles = profile.manifest.files.filter((f) => f.category === 'analyzer');
  const analyzerBatches = await Promise.all(analyzerFiles.map((f) => parseAnalyzerFile(f.absolutePath)));
  const analyzerResults = mergeAnalyzerResults(analyzerBatches);
  const resourceFiles = profile.manifest.files.filter((f) => f.category === 'kubernetes-resource');
  const resourceBatches = await Promise.all(resourceFiles.map((f) => parseResourceFile(f.absolutePath)));
  const resources = resourceBatches.flat();
  const eventFiles = profile.manifest.files.filter((f) => f.category === 'event');
  const eventBatches = await Promise.all(eventFiles.map((f) => parseEventFile(f.absolutePath)));
  const events = sortEventsByTime(eventBatches.flat());
  const logEntries = identifyLogFiles(profile.manifest);
  const logs = await Promise.all(logEntries.map((f) => parseLogFile(f.absolutePath)));
  const helmFiles = profile.manifest.files.filter((f) => f.category === 'helm-release');
  const helmBatches = await Promise.all(helmFiles.map((f) => parseHelmReleaseFile(f.absolutePath)));
  const helmReleases = helmBatches.flat();

  const resourceSourceFiles = new Map();
  for (let i = 0; i < resourceFiles.length; i++) {
    const file = resourceFiles[i]!;
    const batch = resourceBatches[i] ?? [];
    for (const resource of batch) resourceSourceFiles.set(resource, file.relativePath);
  }

  const seeds = generateSeeds({
    analyzerResults,
    resources,
    events,
    logs,
    profile,
    resourceSourceFiles,
    helmReleases,
  });

  fs.rmSync(tmpDir, { recursive: true, force: true });
  return seeds;
}

describe('scratch cassette seeds', () => {
  it('prints seeds for bad-image-tag and missing-secret-crashloop', async () => {
    for (const scenario of ['bad-image-tag', 'missing-secret-crashloop']) {
      const seeds = await loadSeeds(scenario);
      console.log(`SCENARIO=${scenario}`);
      console.log(JSON.stringify(seeds, null, 2));
    }
  });
});
