import { describe, it } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { analyzeBundlePipeline, cleanupPipelineResult } from '../../../src/pipeline/analyze.js';
import { createTestBundle, getFixturePath } from '../../helpers/create-test-bundle.js';

describe('scratch cassette results', () => {
  it('prints replay findings for two scenarios', async () => {
    process.env['SBI_AI_MODE'] = 'replay';
    process.env['SBI_CASSETTE_DIR'] = path.resolve('test/fixtures/cassettes');
    delete process.env['OPENAI_API_KEY'];

    for (const scenario of ['bad-image-tag', 'missing-secret-crashloop']) {
      const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), `sbi-cassette-${scenario}-`));
      const bundlePath = await createTestBundle(getFixturePath(scenario), path.join(tmpDir, `${scenario}.tar.gz`));
      const result = await analyzeBundlePipeline(bundlePath);
      console.log(`SCENARIO=${scenario}`);
      console.log(JSON.stringify(result.findings.map((f) => ({ id: f.id, title: f.title, confidence: f.confidence })), null, 2));
      await cleanupPipelineResult(result);
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  });
});

