      edges.push({
        id: `edge:hypothesis-support:${finding.id}:${i}`,
        source: `evidence:${evidence.path}`,
        target: finding.id,
        type: 'supports',
        weight: finding.confidence,
        note: 'Structured hypothesis evidence supports this differential-diagnosis candidate',
