export { CommanderError };

import * as fsp from 'fs/promises';
import * as path from 'path';
import type { BundleProfile } from '../types/index.js';
import type { InvestigationTrace } from '../pipeline/trace.js';
import type { PipelineResult } from '../pipeline/analyze.js';
import {
  buildReport,
  generateJsonReport,
  generateMarkdownReport,
  generateHtmlReport,
  writeJsonReport,
} from '../reporters/index.js';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface OutputOptions {
  format: 'json' | 'text' | 'summary' | 'markdown' | 'html';
  outputDir?: string;
  verbose?: boolean;
}

// ---------------------------------------------------------------------------
// Console output
// ---------------------------------------------------------------------------

/**
 * Prints a human-readable summary of the bundle profile to stdout.
 */
export function printProfileSummary(profile: BundleProfile): void {
  const { manifest, analyzerCount, logFileCount, resourceCount, eventCount } = profile;

  console.log('');
  console.log('═══════════════════════════════════════════════════════');
  console.log('  Support Bundle Profile');
  console.log('═══════════════════════════════════════════════════════');
  console.log(`  Bundle:       ${manifest.bundlePath}`);
  console.log(`  Files:        ${manifest.files.length}`);
  console.log(`  Analyzers:    ${analyzerCount}`);
  console.log(`  Resources:    ${resourceCount}`);
  console.log(`  Events:       ${eventCount}`);
  console.log(`  Log files:    ${logFileCount}`);
  console.log('');

  if (profile.namespaces.length > 0) {
    console.log(`  Namespaces:   ${profile.namespaces.join(', ')}`);
  }

  if (profile.workloads.length > 0) {
    console.log('');
    console.log('  Workloads:');
    for (const wl of profile.workloads) {
      console.log(`    - [${wl.kind}] ${wl.namespace}/${wl.name}`);
    }
  }

  if (profile.coverageGaps.length > 0) {
    console.log('');
    console.log('  Coverage gaps:');
    for (const gap of profile.coverageGaps) {
      console.log(`    ⚠  ${gap}`);
    }
  }

  console.log('═══════════════════════════════════════════════════════');
  console.log('');
}

// ---------------------------------------------------------------------------
// File output
// ---------------------------------------------------------------------------

/**
 * Writes the investigation trace to a JSON file in `outputDir`.
 */
export async function writeTraceFile(
  trace: InvestigationTrace,
  outputDir: string,
): Promise<void> {
  await fsp.mkdir(outputDir, { recursive: true });
  const traceFile = path.join(outputDir, 'trace.json');
  await fsp.writeFile(traceFile, JSON.stringify(trace, null, 2), 'utf-8');
}

/**
 * Prints a text summary of analysis results to stdout.
 *
 * @deprecated Prefer `writePipelineResult` which now uses the Markdown reporter.
 *             Kept for backward-compatible re-exports.
 */
export function printTextSummary(result: PipelineResult): void {
  printProfileSummary(result.profile);

  const errors = result.analyzerResults.filter((r) => r.isFail);
  const warns = result.analyzerResults.filter((r) => r.isWarn);

  if (errors.length > 0) {
    console.log('  ❌  Analyzer Errors:');
    for (const e of errors) {
      console.log(`    [${e.name}] ${e.title}`);
      if (e.message) console.log(`      ${e.message}`);
    }
    console.log('');
  }

  if (warns.length > 0) {
    console.log('  ⚠   Analyzer Warnings:');
    for (const w of warns) {
      console.log(`    [${w.name}] ${w.title}`);
      if (w.message) console.log(`      ${w.message}`);
    }
    console.log('');
  }
}

/**
 * Writes the pipeline result to disk or prints to stdout depending on the
 * output options.
 *
 * When `outputDir` is set, always writes all three report files:
 *   - `findings.json`  — full structured report (via JSON reporter)
 *   - `report.md`      — human-readable Markdown report
 *   - `report.html`    — self-contained HTML report with embedded CSS
 *
 * When `outputDir` is not set, format controls stdout output:
 *   - `json`           — prints full JSON report to stdout
 *   - `text`           — prints Markdown report to stdout
 *   - `markdown`       — prints Markdown report to stdout
 *   - `html`           — prints HTML report to stdout
 *   - `summary`        — prints bundle profile summary to stdout
 */
export async function writePipelineResult(
  result: PipelineResult,
  options: OutputOptions,
): Promise<void> {
  const { format, outputDir } = options;

  if (outputDir) {
    // Always write all three report files when an output directory is provided.
    const resolvedDir = path.resolve(outputDir);
    await fsp.mkdir(resolvedDir, { recursive: true });

    const report = buildReport(result);

    await writeJsonReport(report, resolvedDir);

    const mdPath = path.join(resolvedDir, 'report.md');
    await fsp.writeFile(mdPath, generateMarkdownReport(report), 'utf-8');

    const htmlPath = path.join(resolvedDir, 'report.html');
    await fsp.writeFile(htmlPath, generateHtmlReport(report), 'utf-8');

    console.log(`Reports written to ${resolvedDir}: findings.json, report.md, report.html`);
    return;
  }

  // No outputDir — print to stdout based on format.
  if (format === 'summary') {
    printProfileSummary(result.profile);
    return;
  }

  const report = buildReport(result);

  if (format === 'json') {
    console.log(generateJsonReport(report));
  } else if (format === 'html') {
    console.log(generateHtmlReport(report));
  } else {
    // 'text' | 'markdown'
    console.log(generateMarkdownReport(report));
  }
}

import * as fsp from 'fs/promises';
import * as path from 'path';
import type { InvestigationReport } from './types.js';
import { cleanEvidencePath, humanizeTitle } from './display-helpers.js';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Identifies the schema version of the JSON output.  Increment on breaking changes. */
const REPORT_SCHEMA_VERSION = '1.0.0';

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Serializes an {@link InvestigationReport} to a well-structured JSON string.
 *
 * The output includes:
 * - Report metadata: `schemaVersion` and `generatedAt` (ISO-8601 timestamp).
 * - All top-level report fields: `executiveSummary`, `rootCause`,
 *   `evidenceReferences`, `contradictions`, `nextSteps`, `missingEvidence`,
 *   and `specRecommendations`.
 * - A `findings` array where every finding is serialized with its full set of
 *   fields: `id`, `title`, `severity`, `confidence`, `affectedComponents`,
 *   `reasoningSummary`, `evidence`, `contradictionsChecked`,
 *   `recommendedAction`, and `missingEvidence`.
 *
 * The JSON is formatted with 2-space indentation for human readability.  The
 * output is safe for `JSON.parse` round-tripping — no circular references, no
 * class instances, no functions.
 *
 * @param report - The investigation report to serialize.
 * @returns A JSON string representing the full investigation report.
 */
export function generateJsonReport(report: InvestigationReport): string {
  const output = {
    schemaVersion: REPORT_SCHEMA_VERSION,
    generatedAt: new Date().toISOString(),
    executiveSummary: report.executiveSummary,
    rootCause: report.rootCause,
    findings: report.findings.map((finding) => {
      const base = {
        id: finding.id,
        title: humanizeTitle(finding.title),
        severity: finding.severity,
        confidence: finding.confidence,
        affectedComponents: finding.affectedComponents.map(cleanEvidencePath),
        reasoningSummary: finding.reasoningSummary,
        evidence: finding.evidence.map((ev) => {
          const evOut: Record<string, unknown> = {
            path: cleanEvidencePath(ev.path),
            note: ev.note,
          };
          if (ev.artifactType !== undefined) {
            evOut['artifactType'] = ev.artifactType;
          }
          if (ev.timestamp !== undefined) {
            evOut['timestamp'] = ev.timestamp;
          }
          return evOut;
        }),
        contradictionsChecked: finding.contradictionsChecked,
        recommendedAction: finding.recommendedAction,
        missingEvidence: finding.missingEvidence,
        ...(finding.confidenceQuality !== undefined
          ? { confidenceQuality: finding.confidenceQuality }
          : {}),
      };
      return base;
    }),
    evidenceReferences: report.evidenceReferences.map((ev) => ({
      path: cleanEvidencePath(ev.path),
      note: ev.note,
    })),
    contradictions: report.contradictions,
    nextSteps: report.nextSteps,
    missingEvidence: report.missingEvidence,
    specRecommendations: report.specRecommendations,
  };

  return JSON.stringify(output, null, 2);
}

/**
 * Writes an {@link InvestigationReport} as a JSON file to disk.
 *
 * The report is written to `findings.json` inside `outputDir`.  The directory
 * is created recursively if it does not already exist.
 *
 * @param report    - The investigation report to write.
 * @param outputDir - Directory where `findings.json` will be created.
 * @returns The absolute path of the written file.
 */
export async function writeJsonReport(
  report: InvestigationReport,
  outputDir: string,
): Promise<string> {
  const resolvedOutputDir = path.resolve(outputDir);
  await fsp.mkdir(resolvedOutputDir, { recursive: true });
  const outFile = path.join(resolvedOutputDir, 'findings.json');
  await fsp.writeFile(outFile, generateJsonReport(report), 'utf-8');
  return outFile;
}

import type { PipelineResult } from '../pipeline/analyze.js';
import type { Finding } from '../types/index.js';
import type { InvestigationReport } from './types.js';
import { generateSpecRecommendations } from './spec-recommender.js';
import { cleanEvidencePath, humanizeTitle } from './display-helpers.js';

// ---------------------------------------------------------------------------
// AI finding helpers
// ---------------------------------------------------------------------------

/**
 * Returns `true` when a finding was produced by the AI investigator.
 *
 * AI findings carry IDs prefixed with `finding:ai:`, assigned by
 * `convertAIFindings` in the AI investigator.
 */
export function isAIFinding(finding: Finding): boolean {
  return finding.id.startsWith('finding:ai:');
}

/**
 * Returns the number of distinct `artifactType` values across all evidence
 * items in a finding.
 *
 * A value of 2 or more means the finding corroborates evidence from at least
 * two different artifact categories (e.g., log + kubernetes-resource), which
 * indicates cross-source correlation.
 */
function countDistinctArtifactTypes(finding: Finding): number {
  const types = new Set<string>();
  for (const ev of finding.evidence) {
    if (ev.artifactType !== undefined && ev.artifactType.trim().length > 0) {
      types.add(ev.artifactType);
    }
  }
  return types.size;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Generates a concise, human-readable executive summary from the ranked list
 * of findings and the bundle profile.
 *
 * When no findings are present the summary states that no significant issues
 * were detected.  When findings are present the summary names the top finding,
 * states the overall count and highest severity level, and quotes the
 * recommended action so a reader can act immediately.
 *
 * When AI-augmented findings are present, the summary appends a sentence
 * noting AI analysis was used along with the count of AI findings.
 */
function generateExecutiveSummary(findings: Finding[]): string {
  if (findings.length === 0) {
    return (
      'No significant issues were identified in this support bundle. ' +
      'All investigated conditions appear normal.'
    );
  }

  const topFinding = findings[0]!;
  const criticalCount = findings.filter((f) => f.severity === 'critical').length;
  const highCount = findings.filter((f) => f.severity === 'high').length;

  const severitySummary =
    criticalCount > 0
      ? `${criticalCount} critical issue${criticalCount > 1 ? 's' : ''} require${criticalCount === 1 ? 's' : ''} immediate attention.`
      : highCount > 0
        ? `${highCount} high-severity issue${highCount > 1 ? 's' : ''} ${highCount === 1 ? 'was' : 'were'} found.`
        : '';

  const confidencePct = Math.round(topFinding.confidence * 100);

  const aiFindings = findings.filter(isAIFinding);
  const aiFindingCount = aiFindings.length;
  const crossSourceAIFindingCount = aiFindings.filter(
    (finding) => countDistinctArtifactTypes(finding) >= 2,
  ).length;
  const aiNote =
    aiFindingCount > 0
      ? crossSourceAIFindingCount > 0
        ? `AI-augmented analysis contributed ${aiFindingCount} finding${aiFindingCount > 1 ? 's' : ''}, including ${crossSourceAIFindingCount} with cross-source evidence correlation.`
        : `AI-augmented analysis contributed ${aiFindingCount} finding${aiFindingCount > 1 ? 's' : ''}.`
      : '';

  return [
    `Investigation identified ${findings.length} finding${findings.length > 1 ? 's' : ''}.`,
    severitySummary,
    `Most significant: ${humanizeTitle(topFinding.title)} (confidence: ${confidencePct}%).`,
    `Recommended action: ${topFinding.recommendedAction}`,
    aiNote,
  ]
    .filter(Boolean)
    .join(' ');
}

/**
 * Derives a root-cause string from the verified findings list.
 *
 * Selection logic (in priority order):
 * 1. AI findings with evidence spanning 2+ distinct `artifactType` values
 *    (cross-source correlation — most trustworthy causal explanation).
 * 2. All other findings (first by severity+confidence ordering, which callers
 *    are expected to preserve before passing findings here).
 *
 * Returns `null` when there are no findings.
 */
function deriveRootCause(findings: Finding[]): string | null {
  if (findings.length === 0) return null;

  // Prefer cross-source AI findings (evidence from 2+ distinct artifact types)
  const crossSourceAI = findings.filter(
    (f) => isAIFinding(f) && countDistinctArtifactTypes(f) >= 2,
  );
  if (crossSourceAI.length > 0) {
    return crossSourceAI[0]!.reasoningSummary;
  }

  // Fall back to the highest-ranked finding (callers sort by severity desc, confidence desc)
  return findings[0]!.reasoningSummary;
}

/**
 * Collects all evidence references across findings, deduplicating by path.
 * The first note encountered for a given path is retained.
 */
function collectEvidenceReferences(
  findings: Finding[],
): Array<{ path: string; note: string }> {
  const seen = new Set<string>();
  const refs: Array<{ path: string; note: string }> = [];

  for (const finding of findings) {
    for (const ev of finding.evidence) {
      const cleanedPath = cleanEvidencePath(ev.path);
      if (!seen.has(cleanedPath)) {
        seen.add(cleanedPath);
        refs.push({ path: cleanedPath, note: ev.note });
      }
    }
  }

  return refs;
}

/**
 * Generic helper: flattens a string field from every finding, deduplicating
 * by exact string equality while preserving insertion order.
 */
function collectDeduped(
  getItems: (finding: Finding) => string[],
  findings: Finding[],
): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const finding of findings) {
    for (const item of getItems(finding)) {
      if (!seen.has(item)) {
        seen.add(item);
        result.push(item);
      }
    }
  }

  return result;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Assembles an {@link InvestigationReport} from a completed
 * {@link PipelineResult}.
 *
 * The function:
 * 1. Generates an **executive summary** naming the most critical finding,
 *    the total finding count, and the recommended immediate action.
 * 2. Passes the already-ranked `findings[]` through unchanged (the
 *    orchestrator sorts them by severity then confidence).
 * 3. Derives the **root cause** from the highest-ranked finding's
 *    `reasoningSummary`.
 * 4. Collects deduplicated **evidence references**, **contradictions**,
 *    **next steps**, and **missing evidence** across all findings.
 * 5. Calls {@link generateSpecRecommendations} to produce collector,
 *    analyzer, and redaction suggestions from evidence gaps and the bundle
 *    profile's coverage gaps.
 *
 * All fields in the returned report are serialisation-safe (no class
 * instances, no functions) so the result can be passed directly to any of
 * the three reporters.
 *
 * @param result - The completed pipeline result containing findings, profile,
 *                 and all parsed bundle data.
 * @returns A fully assembled {@link InvestigationReport}.
 */
export function buildReport(result: PipelineResult): InvestigationReport {
  const { findings, profile } = result;

  const executiveSummary = generateExecutiveSummary(findings);
  const rootCause = deriveRootCause(findings);
  const specRecommendations = generateSpecRecommendations(findings, profile);
  const evidenceReferences = collectEvidenceReferences(findings);
  const contradictions = collectDeduped((f) => f.contradictionsChecked, findings);
  const nextSteps = collectDeduped((f) => [f.recommendedAction], findings);
  const missingEvidence = collectDeduped((f) => f.missingEvidence, findings);

  return {
    executiveSummary,
    findings,
    rootCause,
    evidenceReferences,
    contradictions,
    nextSteps,
    missingEvidence,
    specRecommendations,
  };
}

import type { Finding } from '../types/index.js';

// ---------------------------------------------------------------------------
// SpecRecommendation
// ---------------------------------------------------------------------------

/**
 * A recommendation to improve the support bundle specification, generated
 * from evidence gaps and heuristic findings discovered during investigation.
 *
 * - `collector`  — suggests adding or expanding a data collector so future
 *                  bundles contain the missing artifact class.
 * - `analyzer`   — suggests adding a deterministic analyzer to replace a
 *                  heuristic finding (improves precision and repeatability).
 * - `redaction`  — suggests adding a redaction rule when sensitive data paths
 *                  appear in evidence but no existing rule covers them.
 */
export type SpecRecommendationType = 'collector' | 'analyzer' | 'redaction';

export interface SpecRecommendation {
  /** The category of spec improvement being suggested. */
  type: SpecRecommendationType;
  /**
   * Human-readable description of the recommended spec change.
   * Should be concise and actionable (one or two sentences).
   */
  description: string;
  /**
   * Explanation of why this recommendation was generated — which evidence gap
   * or heuristic finding triggered it, so the suggestion is traceable.
   */
  rationale: string;
}

// ---------------------------------------------------------------------------
// ReportOptions
// ---------------------------------------------------------------------------

export type ReportFormat = 'markdown' | 'html' | 'json';

/**
 * Configuration options controlling how a report is written to disk.
 *
 * - `format`        — output format (default: `'markdown'`)
 * - `outputDir`     — directory where the report file will be written
 *                     (default: current working directory)
 * - `includeTrace`  — when `true`, the full investigation trace is appended
 *                     as a separate section / field in the report
 */
export interface ReportOptions {
  format?: ReportFormat;
  outputDir?: string;
  includeTrace?: boolean;
}

// ---------------------------------------------------------------------------
// InvestigationReport
// ---------------------------------------------------------------------------

/**
 * The top-level output of the reporting layer.
 *
 * All fields are serialisation-safe (no class instances, no functions) so the
 * report can be written to JSON, Markdown, or HTML without transformation.
 */
export interface InvestigationReport {
  /**
   * High-level narrative written for a human reader — typically 2–4 sentences
   * summarising the most critical finding, the overall confidence, and the
   * recommended immediate action.
   */
  executiveSummary: string;

  /**
   * Verified, deduplicated findings sorted by severity then confidence
   * (highest first).  This is the primary payload for report consumers.
   */
  findings: Finding[];

  /**
   * The single most likely root cause for the observed symptoms.  Derived
   * from the highest-ranked finding; may be `null` when no findings exist.
   */
  rootCause: string | null;

  /**
   * Flat list of all evidence references cited across every finding, with
   * duplicates removed.  Useful for report sections that list all touched
   * files in one place.
   */
  evidenceReferences: Array<{ path: string; note: string }>;

  /**
   * Union of `contradictionsChecked` strings across all findings, with
   * duplicates removed.  Surfaces the "what we checked and ruled out"
   * narrative for the reader.
   */
  contradictions: string[];

  /**
   * Consolidated recommended next steps drawn from `recommendedAction` on
   * every finding (highest-severity first).  Duplicates are removed.
   */
  nextSteps: string[];

  /**
   * Union of `missingEvidence` strings across all findings, with duplicates
   * removed.  Tells the reader what additional data would improve confidence.
   */
  missingEvidence: string[];

  /**
   * Suggestions for improving the support bundle spec — collectors, analyzers,
   * or redaction rules that should be added to prevent evidence gaps in future
   * bundles.  Empty when the investigation found sufficient coverage.
   */
  specRecommendations: SpecRecommendation[];
}

import type { AnalyzerResult, BundleProfile, K8sEvent, K8sResource } from '../types/index.js';
import type { Finding } from '../types/index.js';
import type { GraphEdge } from '../types/index.js';
import type { LogFile, HelmRelease } from '../parsers/index.js';

// ---------------------------------------------------------------------------
// Seed categories
// ---------------------------------------------------------------------------

/**
 * The kind of investigation that a seed targets.
 *
 * - `kubernetes`    — Pod lifecycle, workload health, events
 * - `log`           — High-importance log files with significant errors
 * - `configuration` — Missing secrets, wrong config values, env mismatches
 * - `connectivity`  — DNS resolution failures, unreachable endpoints, networking
 */
export type SeedCategory = 'kubernetes' | 'log' | 'configuration' | 'connectivity';

// ---------------------------------------------------------------------------
// InvestigationSeed
// ---------------------------------------------------------------------------

/**
 * A single hypothesis to be investigated, generated from parsed bundle data.
 *
 * Seeds are sorted by {@link priority} (highest first) so investigators work
 * on the most actionable leads first.
 */
export interface InvestigationSeed {
  /** Unique identifier within a seed generation run. */
  id: string;
  /** Human-readable description of what to investigate. */
  hypothesis: string;
  /** Identifier of the artifact or rule that produced the seed. */
  source: string;
  /** Which investigator type this seed targets. */
  category: SeedCategory;
  /** Urgency / importance in [0, 100]. Higher = more important. */
  priority: number;
}

// ---------------------------------------------------------------------------
// InvestigatorContext
// ---------------------------------------------------------------------------

/**
 * All parsed bundle data made available to investigators and the seed
 * generator.  Mirrors the data-bearing fields of `PipelineResult` without
 * the graph or trace — those are pipeline-level concerns.
 */
export interface InvestigatorContext {
  analyzerResults: AnalyzerResult[];
  resources: K8sResource[];
  events: K8sEvent[];
  logs: LogFile[];
  profile: BundleProfile;
  /**
   * Maps each parsed K8sResource to the relative source file path it was
   * loaded from (e.g. `cluster-resources/pods/default.json`).  Used by
   * `buildChunkIndex` to set accurate `artifactId` values instead of
   * fabricating a per-resource path.
   *
   * Optional: when absent, `buildChunkIndex` falls back to a constructed path.
   */
  resourceSourceFiles?: Map<K8sResource, string>;
  /**
   * Helm releases parsed from `helm-release` classified files in the bundle.
   *
   * Optional: when absent, no Helm release chunks are produced.
   */
  helmReleases?: HelmRelease[];
}

// ---------------------------------------------------------------------------
// ClusteredSeed
// ---------------------------------------------------------------------------

/**
 * An {@link InvestigationSeed} that has been processed by the AI seed-clustering
 * pass. Extends the base seed with cluster membership metadata so downstream
 * investigators (especially the AI investigator) have full context about all
 * the original seeds collapsed into this representative.
 *
 * ## How clustering works
 *
 * After `generateSeeds()` produces the raw deterministic seed list, an optional
 * LLM clustering pass groups seeds by likely shared root cause.  Within each
 * group, all seeds are collapsed into a single representative `ClusteredSeed`:
 *
 * - **`hypothesis`** — concatenation of all member hypotheses joined by
 *   `'\n\nAlso investigate: '` (the same separator used by `createMergedSeed`
 *   in `ai-investigator.ts`).  This ensures lexical search, HyDE embedding,
 *   and the LLM prompt all cover every member symptom.
 * - **`source`** — the highest-priority member's source (used by graph
 *   retrieval to find the primary resource).  Additional member sources are
 *   accessible via `memberSeeds`.
 * - **`priority`** — re-scored upward when multiple seeds converge (see
 *   `originalPriority` for the pre-cluster value).
 * - **`category`** — inherited from the highest-priority member.
 *
 * Seeds that are not grouped (singleton clusters) are still wrapped as
 * `ClusteredSeed` for type uniformity:
 * - `memberSeeds` = `[self]`
 * - `clusterLabel` = the original `hypothesis`
 * - `originalPriority` = `priority` (unchanged)
 */
export interface ClusteredSeed extends InvestigationSeed {
  /**
   * All original seeds collapsed into this cluster representative, including
   * the representative itself as the first element.
   *
   * Downstream consumers (the AI investigator) need the full seed objects —
   * not just IDs — because `seed.source` is parsed for graph traversal and
   * `seed.hypothesis` is used for lexical search and HyDE embedding.
   *
   * For unclustered (singleton) seeds this is `[self]` — a single-element
   * array containing the seed itself.
   */
  memberSeeds: InvestigationSeed[];

  /**
   * LLM-generated shared root-cause label for the cluster.
   *
   * Example: `'CrashLoopBackOff in namespace default'`.
   *
   * For unclustered seeds this equals the original `hypothesis` string.
   */
  clusterLabel: string;

  /**
   * The seed priority **before** the cluster re-scoring boost was applied.
   *
   * Useful for audit trails and debugging — shows how much the clustering
   * step raised the urgency of this lead.
   *
   * For unclustered seeds `originalPriority === priority`.
   */
  originalPriority: number;
}

// ---------------------------------------------------------------------------
// SeedClusterLLMClient
// ---------------------------------------------------------------------------

/**
 * Minimal LLM client interface required by the seed-clustering pass.
 *
 * Mirrors the {@link HydeLLMClient} pattern from `src/ai/hyde.ts`: only a
 * plain-text generation method is needed — no JSON mode, no schema validation.
 * The real {@link LLMClient} satisfies this interface without any adapter
 * because it already implements `generateText`.
 *
 * Mock implementations for testing only need to provide this single method.
 *
 * @example
 * ```typescript
 * const mockClient: SeedClusterLLMClient = {
 *   generateText: async (_sys, _user) => JSON.stringify({ clusters: [] }),
 * };
 * ```
 */
export interface SeedClusterLLMClient {
  /**
   * Generates free-form text (including JSON) given a system and user prompt.
   *
   * Implementations should throw on network/API failure so that the clustering
   * pass can detect the error, fall back gracefully, and continue with the
   * original unclustered seeds.
   *
   * @param systemPrompt - System-level context for the clustering task.
   * @param userPrompt   - User-facing prompt carrying the serialised seed list.
   * @returns Generated text string (expected to be a JSON object).
   */
  generateText(systemPrompt: string, userPrompt: string): Promise<string>;
}

