  const aiFirst = [...findings].sort((a, b) => {
    const aIsAi = a.id.startsWith('finding:ai:') ? 0 : 1;
    const bIsAi = b.id.startsWith('finding:ai:') ? 0 : 1;
    return aIsAi - bIsAi;
