  function unionStrings(...arrays: string[][]): string[] {
    const seen = new Set<string>();
    const result: string[] = [];
    for (const arr of arrays) {
      for (const s of arr) {
        if (!seen.has(s)) {
          seen.add(s);
          result.push(s);
        }
      }
    }
