} from '../../types/index.js';
import type { LogFile, LogLine } from '../../parsers/index.js';
import type {
  InvestigatorContext,
  InvestigationSeed,
} from '../types.js';
import { investigateKubernetes } from '../kubernetes-investigator.js';
import { investigateLog } from '../log-investigator.js';
