export function toAIRunSummary(
  stats: AIRunStats,
  backend: AIRunSummary['backend'],
  fallbackModel?: string,
): AIRunSummary {
  return {
    ...stats,
    model: backend === 'off' ? 'off' : stats.model || fallbackModel || 'unknown',
    backend,
  };
}

