 *
 * - `collector`  — suggests adding or expanding a data collector so future
 *                  bundles contain the missing artifact class.
 * - `analyzer`   — suggests adding a deterministic analyzer to replace a
 *                  heuristic finding (improves precision and repeatability).
 * - `redaction`  — suggests adding a redaction rule when sensitive data paths
 *                  appear in evidence but no existing rule covers them.
 */
export type SpecRecommendationType = 'collector' | 'analyzer' | 'redaction';

export interface SpecRecommendation {
  /** The category of spec improvement being suggested. */
  type: SpecRecommendationType;
  /**
   * Human-readable description of the recommended spec change.
   * Should be concise and actionable (one or two sentences).
   */
  description: string;
  /**
   * Explanation of why this recommendation was generated — which evidence gap
   * or heuristic finding triggered it, so the suggestion is traceable.
   */
  rationale: string;
}

// ---------------------------------------------------------------------------
// ReportOptions
// ---------------------------------------------------------------------------

export type ReportFormat = 'markdown' | 'html' | 'json';

/**
 * Configuration options controlling how a report is written to disk.
 *
 * - `format`        — output format (default: `'markdown'`)
 * - `outputDir`     — directory where the report file will be written
 *                     (default: current working directory)
 * - `includeTrace`  — when `true`, the full investigation trace is appended
 *                     as a separate section / field in the report
 */
export interface ReportOptions {
  format?: ReportFormat;
  outputDir?: string;
  includeTrace?: boolean;
}

// ---------------------------------------------------------------------------
// InvestigationReport
// ---------------------------------------------------------------------------

/**
 * The top-level output of the reporting layer.
 *
 * All fields are serialisation-safe (no class instances, no functions) so the
 * report can be written to JSON, Markdown, or HTML without transformation.
 */
export interface InvestigationReport {
  /**
   * High-level narrative written for a human reader — typically 2–4 sentences
   * summarising the most critical finding, the overall confidence, and the
   * recommended immediate action.
   */
  executiveSummary: string;

  /**
   * Verified, deduplicated findings sorted by severity then confidence
   * (highest first).  This is the primary payload for report consumers.
   */
  findings: Finding[];

  /**
   * The single most likely root cause for the observed symptoms.  Derived
   * from the highest-ranked finding; may be `null` when no findings exist.
   */
  rootCause: string | null;

  /**
   * Flat list of all evidence references cited across every finding, with
   * duplicates removed.  Useful for report sections that list all touched
   * files in one place.
   */
  evidenceReferences: Array<{ path: string; note: string }>;

  /**
   * Union of `contradictionsChecked` strings across all findings, with
   * duplicates removed.  Surfaces the "what we checked and ruled out"
   * narrative for the reader.
   */
  contradictions: string[];

  /**
   * Consolidated recommended next steps drawn from `recommendedAction` on
   * every finding (highest-severity first).  Duplicates are removed.
   */
  nextSteps: string[];

  /**
   * Union of `missingEvidence` strings across all findings, with duplicates
   * removed.  Tells the reader what additional data would improve confidence.
   */
  missingEvidence: string[];

  /**
   * Suggestions for improving the support bundle spec — collectors, analyzers,
   * or redaction rules that should be added to prevent evidence gaps in future
   * bundles.  Empty when the investigation found sufficient coverage.
   */
  specRecommendations: SpecRecommendation[];

  /** Summary of AI model usage, latency, and token/cost telemetry for this run. */
  aiSummary?: AIRunSummary;
}

  // individual hypothesis findings and are subject to the same dedup passes.
  const correlatedMetaFindings = correlateAcrossSymptoms(hypothesisSets);

  // Convert hypothesis sets to findings, keeping only those with positive
  // confidence (at least one supporting evidence item contributed to the score).
  const allHypothesisFindings = convertHypothesisSetsToFindings(hypothesisSets);

  const convertedHypothesisFindings = allHypothesisFindings.filter((hf) => hf.confidence > 0);

  // Include both converted hypothesis findings (fallback path) and graph
  // root-cause findings (graph-driven path) in the combined pool that Pass 1
  // processes. The graph root-cause findings are ranked by path length + edge
  // weight + evidence count so the most diagnostic root cause appears first.
  const rankedGraphRootCauses = rankGraphRootCauses(graphRootCauseFindings, causalInstances);
  const nonZeroHypothesisFindings = [
    ...convertedHypothesisFindings,
    ...correlatedMetaFindings,
    ...rankedGraphRootCauses,
  ];

  // ── 4. AI investigation (additive, with graceful degradation) ─────────────
  const rawFindings: Finding[] = [...heuristicFindings];
  let aiEnabled = false;
  let aiFindings = 0;
  let retrievalStats = {
    graphChunks: 0,
    lexicalChunks: 0,
    semanticChunks: 0,
    mergedChunks: 0,
  };
  let aiRunStats = zeroAIRunStats('unknown');

  if (aiDeps !== undefined) {
    try {
      const aiResult = await investigateWithAI(context, clusteredSeeds, {
        ...aiDeps,
        onSeedProgress,
      });
      rawFindings.push(...aiResult.findings);
      allEdges.push(...aiResult.edges);
      aiEnabled = true;
      aiFindings = aiResult.findings.length;
      retrievalStats = aiResult.metadata?.retrievalStats ?? retrievalStats;
      aiRunStats = aiResult.metadata?.aiRunStats ?? aiRunStats;
    } catch (error) {
      // Graceful degradation: log the failure, continue with heuristic results
      console.warn(
        `[Orchestrator] AI investigation failed, continuing with heuristic results: ` +
          `${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }

  // ── 5. Verify: contradiction checks, confidence adjustment, dedup ─────────
  //
  // Applies per-finding contradiction checks, confidence adjustment, and
  // missing-evidence detection, then deduplicates within the heuristic + AI
  // pool by issue type + primary component.
  const verifiedHeuristic = verifyFindings(rawFindings, context);

  // ── 6. Pass 1: Component-based merge ─────────────────────────────────────
  //
  // All findings — verified heuristic, AI, and hypothesis — are combined and
  // grouped by (primaryComponent, issueFamily).  Within each group the
  // highest-priority finding wins (AI > hypothesis > heuristic) and absorbs
  // evidence from non-winning findings via {@link mergeComponentGroup}.
  //
  // This single pass replaces three previously-overlapping steps:
  //   (a) hypothesisDedupMap — per-category hypothesis dedup
  //   (b) AI-primary promotion — AI absorbs heuristic for same component
  //   (c) mergeHypothesisFindings — hypothesis replaces heuristic for same
  //       component + issue family
  //
  // Findings from different issue families on the same component remain
  // separate (e.g. CrashLoopBackOff and missing-secret both survive for the
  // same pod).
  const pass1Result = pass1ComponentMerge(verifiedHeuristic, nonZeroHypothesisFindings);

  // Build hypothesis support edges from all nonZero hypothesis findings;
  // any edges pointing to findings absorbed by Pass 1 are cleaned up at the
  // end via filterEdgesForRetainedFindings.
  const retainedEdges = filterEdgesForRetainedFindings(allEdges, pass1Result);
  const hypothesisEdges = buildHypothesisSupportEdges(nonZeroHypothesisFindings);
  const combinedEdges = [...retainedEdges, ...hypothesisEdges];

  // ── 7. Pass 2: Title-based dedup ─────────────────────────────────────────
  //
  // Catches cosmetic wording variants that survived Pass 1 because they
  // reference different components (e.g. the same missing Secret affecting
  // two pods, or LLM findings with rephrased titles).  Normalises titles via
  // {@link normalizeTitleForPass2} and keeps the higher-confidence entry per
  // normalised title.  AI findings win title collisions before confidence is
  // compared.
  //
  // The full normalised title is the dedup key — no character-count
  // truncation — so findings that differ only after position 80 are kept.
  const dedupedFindings = pass2TitleDedup(pass1Result);

  // ── 8. Symptom suppression (separate post-dedup filter) ─────────────────
  //
  // This is a distinct, third step — not part of the two dedup passes above.
  // It removes pure-symptom heuristic findings once a root-cause finding
  // covers the same component, cleaning up noise from the report.
  //
  // Suppressed finding types (broad symptoms with no diagnostic specificity):
  //   - 'Not Ready Pod'      (finding:k8s:notready:*) — generic readiness symptom
  //   - 'Pending Pod'        (finding:k8s:pending:*)  — generic scheduling symptom
  //   - 'Unhealthy Workload' (finding:k8s:workload:*) — generic workload symptom
  //
  // Preserved finding types (always kept, even when a root-cause exists):
  //   - CrashLoopBackOff  (finding:k8s:crashloop:*) — names the specific failure mode
  //   - ImagePullBackOff  (finding:k8s:imagepull:*)  — names the specific failure mode
  //
  // For 'Not Ready Pod' and 'Pending Pod': suppress when any root-cause
  //   finding has a component that exactly matches one of the symptom
  //   finding's pod components.
  //
  // For 'Unhealthy Workload': suppress when any root-cause finding has a Pod
  //   component in the same namespace as the workload.  This is a sound proxy
  //   for "the workload's pods are already diagnosed".
  const rootCauseFindings = dedupedFindings.filter(
    (f) =>
      (f.id.startsWith('finding:hypothesis:') && f.confidence >= 0.5) ||
      f.id.startsWith('finding:ai:') ||
      // Graph root-cause findings (created by the graph-driven phase) are
      // treated as root-cause findings for suppression purposes — they are
      // structural diagnoses produced by causal template matching.
      graphRootCauseIds.has(f.id),
  );

  // Collect pod components and namespaces covered by root-cause findings
  const rootCausePodComponents = new Set<string>();
  const rootCausePodNamespaces = new Set<string>();

  for (const rcf of rootCauseFindings) {
    for (const comp of rcf.affectedComponents) {
      if (comp.startsWith('Pod/')) {
        rootCausePodComponents.add(comp);
        const parts = comp.split('/');
        if (parts[1] != null) rootCausePodNamespaces.add(parts[1]);
      }
    }
  }

  const suppressedFindings = dedupedFindings.filter((f) => {
    // Suppress 'Not Ready Pod' and 'Pending Pod' when a root-cause finding
    // covers the same pod. These are broad workload symptoms rather than the
    // actual diagnosis once a stronger root cause is available.
    if (
      f.id.startsWith('finding:k8s:notready:') ||
      f.id.startsWith('finding:k8s:pending:')
    ) {
      return !f.affectedComponents.some((comp) => rootCausePodComponents.has(comp));
    }

    // Suppress 'Unhealthy Workload' when a root-cause finding covers a Pod in
    // the same namespace (the workload's pods have been diagnosed)
    if (f.id.startsWith('finding:k8s:workload:')) {
      return !f.affectedComponents.some((comp) => {
        const parts = comp.split('/');
        const ns = parts[1];
        return ns != null && rootCausePodNamespaces.has(ns);
      });
    }

    return true;
  });

  // ── 7c. Sort by severity desc, then confidence desc ───────────────────────
  // Also stamp confidenceQuality on any finding that still lacks it (synthetic
  // root-cause findings from causal templates and heuristic investigators that
  // bypassed verifyFindings don't get it from the verifier path).
  const sortedFindings = [...suppressedFindings]
    .map((f) =>
      f.confidenceQuality !== undefined
        ? f
        : { ...f, confidenceQuality: computeConfidenceQuality(f) },
    )
    .sort((a, b) => {
      const severityDiff =
        (SEVERITY_ORDER[b.severity] ?? 0) - (SEVERITY_ORDER[a.severity] ?? 0);
      if (severityDiff !== 0) return severityDiff;
      return b.confidence - a.confidence;
    });

  // Final graph cleanup: step 7a/7b can remove findings after the first edge
  // filtering pass, so re-filter once more against the final retained finding
  // set to avoid dangling finding-node references in the investigation graph.
  const finalEdges = filterEdgesForRetainedFindings(combinedEdges, sortedFindings);

  // Build the causal finding tree from the final findings and edges.
  // Only 'causes' edges connect findings in a causal chain — other edge types
  // (supports, contradicts, etc.) are ignored by buildFindingTree.
  const findingTree = buildFindingTree(sortedFindings, finalEdges);

  return {
    findings: sortedFindings,
    edges: finalEdges,
    findingTree,
    seeds,
    clusteredSeeds,
    metadata: {
      seedCount: seeds.length,
      rawFindingCount: rawFindings.length + nonZeroHypothesisFindings.length,
      finalFindingCount: sortedFindings.length,
      aiEnabled,
      aiFindings,
      hypothesesGenerated,
      hypothesesVerified,
      hypothesesConverted: convertedHypothesisFindings.length,
      retrievalStats,
      aiRunStats,
      graphMatchedSymptoms,
      seedClusterCount: clusteredSeeds.length,
      seedClusteringEnabled,
    },
  };
}

import type { AnalyzerResult, BundleProfile, K8sEvent, K8sResource } from '../types/index.js';
import type { Finding } from '../types/index.js';
import type { GraphEdge } from '../types/index.js';
import type { LogFile, HelmRelease } from '../parsers/index.js';
import type { AIRunStats } from '../ai/telemetry.js';

// ---------------------------------------------------------------------------
// Seed categories
// ---------------------------------------------------------------------------

/**
 * The kind of investigation that a seed targets.
 *
 * - `kubernetes`    — Pod lifecycle, workload health, events
 * - `log`           — High-importance log files with significant errors
 * - `configuration` — Missing secrets, wrong config values, env mismatches
 * - `connectivity`  — DNS resolution failures, unreachable endpoints, networking
 */
export type SeedCategory = 'kubernetes' | 'log' | 'configuration' | 'connectivity';

// ---------------------------------------------------------------------------
// InvestigationSeed
// ---------------------------------------------------------------------------

/**
 * A single hypothesis to be investigated, generated from parsed bundle data.
 *
 * Seeds are sorted by {@link priority} (highest first) so investigators work
 * on the most actionable leads first.
 */
export interface InvestigationSeed {
  /** Unique identifier within a seed generation run. */
  id: string;
  /** Human-readable description of what to investigate. */
  hypothesis: string;
  /** Identifier of the artifact or rule that produced the seed. */
  source: string;
  /** Which investigator type this seed targets. */
  category: SeedCategory;
  /** Urgency / importance in [0, 100]. Higher = more important. */
  priority: number;
}

// ---------------------------------------------------------------------------
// InvestigatorContext
// ---------------------------------------------------------------------------

/**
 * All parsed bundle data made available to investigators and the seed
 * generator.  Mirrors the data-bearing fields of `PipelineResult` without
 * the graph or trace — those are pipeline-level concerns.
 */
export interface InvestigatorContext {
  analyzerResults: AnalyzerResult[];
  resources: K8sResource[];
  events: K8sEvent[];
  logs: LogFile[];
  profile: BundleProfile;
  /**
   * Maps each parsed K8sResource to the relative source file path it was
   * loaded from (e.g. `cluster-resources/pods/default.json`).  Used by
   * `buildChunkIndex` to set accurate `artifactId` values instead of
   * fabricating a per-resource path.
   *
   * Optional: when absent, `buildChunkIndex` falls back to a constructed path.
   */
  resourceSourceFiles?: Map<K8sResource, string>;
  /**
   * Helm releases parsed from `helm-release` classified files in the bundle.
   *
   * Optional: when absent, no Helm release chunks are produced.
   */
  helmReleases?: HelmRelease[];
}

// ---------------------------------------------------------------------------
// ClusteredSeed
// ---------------------------------------------------------------------------

/**
 * An {@link InvestigationSeed} that has been processed by the AI seed-clustering
 * pass. Extends the base seed with cluster membership metadata so downstream
 * investigators (especially the AI investigator) have full context about all
 * the original seeds collapsed into this representative.
 *
 * ## How clustering works
 *
 * After `generateSeeds()` produces the raw deterministic seed list, an optional
 * LLM clustering pass groups seeds by likely shared root cause.  Within each
 * group, all seeds are collapsed into a single representative `ClusteredSeed`:
 *
 * - **`hypothesis`** — concatenation of all member hypotheses joined by
 *   `'\n\nAlso investigate: '` (the same separator used by `createMergedSeed`
 *   in `ai-investigator.ts`).  This ensures lexical search, HyDE embedding,
 *   and the LLM prompt all cover every member symptom.
 * - **`source`** — the highest-priority member's source (used by graph
 *   retrieval to find the primary resource).  Additional member sources are
 *   accessible via `memberSeeds`.
 * - **`priority`** — re-scored upward when multiple seeds converge (see
 *   `originalPriority` for the pre-cluster value).
 * - **`category`** — inherited from the highest-priority member.
 *
 * Seeds that are not grouped (singleton clusters) are still wrapped as
 * `ClusteredSeed` for type uniformity:
 * - `memberSeeds` = `[self]`
 * - `clusterLabel` = the original `hypothesis`
 * - `originalPriority` = `priority` (unchanged)
 */
export interface ClusteredSeed extends InvestigationSeed {
  /**
   * All original seeds collapsed into this cluster representative, including
   * the representative itself as the first element.
   *
   * Downstream consumers (the AI investigator) need the full seed objects —
   * not just IDs — because `seed.source` is parsed for graph traversal and
   * `seed.hypothesis` is used for lexical search and HyDE embedding.
   *
   * For unclustered (singleton) seeds this is `[self]` — a single-element
   * array containing the seed itself.
   */
  memberSeeds: InvestigationSeed[];

  /**
   * LLM-generated shared root-cause label for the cluster.
   *
   * Example: `'CrashLoopBackOff in namespace default'`.
   *
   * For unclustered seeds this equals the original `hypothesis` string.
   */
  clusterLabel: string;

  /**
   * The seed priority **before** the cluster re-scoring boost was applied.
   *
   * Useful for audit trails and debugging — shows how much the clustering
   * step raised the urgency of this lead.
   *
   * For unclustered seeds `originalPriority === priority`.
   */
  originalPriority: number;
}

// ---------------------------------------------------------------------------
// SeedClusterLLMClient
// ---------------------------------------------------------------------------

/**
 * Minimal LLM client interface required by the seed-clustering pass.
 *
 * Mirrors the {@link HydeLLMClient} pattern from `src/ai/hyde.ts`: only a
 * plain-text generation method is needed — no JSON mode, no schema validation.
 * The real {@link LLMClient} satisfies this interface without any adapter
 * because it already implements `generateText`.
 *
 * Mock implementations for testing only need to provide this single method.
 *
 * @example
 * ```typescript
 * const mockClient: SeedClusterLLMClient = {
 *   generateText: async (_sys, _user) => JSON.stringify({ clusters: [] }),
 * };
 * ```
 */
export interface SeedClusterLLMClient {
  /**
   * Generates free-form text (including JSON) given a system and user prompt.
   *
   * Implementations should throw on network/API failure so that the clustering
   * pass can detect the error, fall back gracefully, and continue with the
   * original unclustered seeds.
   *
   * @param systemPrompt - System-level context for the clustering task.
   * @param userPrompt   - User-facing prompt carrying the serialised seed list.
   * @returns Generated text string (expected to be a JSON object).
   */
  generateText(systemPrompt: string, userPrompt: string): Promise<string>;
}

// ---------------------------------------------------------------------------
// InvestigatorResult
// ---------------------------------------------------------------------------

/**
 * What a targeted investigator produces after examining its seeds.
 *
 * - `findings` — evidence-backed diagnosis entries
 * - `edges`    — new graph relationships discovered during investigation
 */
export interface InvestigatorResult {
  findings: Finding[];
  edges: GraphEdge[];
  metadata?: {
    retrievalStats?: {
      graphChunks: number;
      lexicalChunks: number;
      semanticChunks: number;
      mergedChunks: number;
    };
    aiRunStats?: AIRunStats;
  };
}

