import { runCli } from './cli/runner.js';

export const VERSION = "0.1.0";

// Pipeline
export { analyzeBundlePipeline, cleanupPipelineResult } from './pipeline/index.js';
export type {
  PipelineOptions,
  PipelineResult,
  PipelineProgressEvent,
  PipelineStepStatus,
} from './pipeline/index.js';
export type { InvestigationTrace, TraceStep } from './pipeline/index.js';

// CLI helpers
export { parseArgs, CommanderError } from './cli/index.js';
export type { ParsedArgs, OutputFormat } from './cli/index.js';
export {
  printProfileSummary,
  printTextSummary,
  writeTraceFile,
  writePipelineResult,
} from './cli/index.js';
export type { OutputOptions } from './cli/index.js';
export { runCli } from './cli/runner.js';

// ── Retrieval infrastructure ──────────────────────────────────────────────────
// Re-exported for benchmark scripts and downstream consumers that need
// direct access to the retrieval pipeline without invoking the full CLI.

export { buildChunkIndex } from './ai/chunk-indexer.js';
export type { IndexedChunk } from './ai/chunk-indexer.js';
export { LexicalSearchIndex } from './ai/lexical-search.js';
export { computeRetrievalMetrics, aggregateRetrievalMetrics } from './ai/retrieval-metrics.js';
export type { RetrievalMetrics } from './ai/retrieval-metrics.js';

export { buildResourceGraph, getRelatedChunks } from './graph/resource-graph.js';
export type { ResourceRelationshipGraph, GraphScoredChunk } from './graph/resource-graph.js';

export { parseResourceJson } from './parsers/k8s-resource-parser.js';
export { parseEventsJson } from './parsers/event-parser.js';
export { parseLogFile } from './parsers/log-parser.js';

if (typeof require !== 'undefined' && typeof module !== 'undefined' && require.main === module) {
  runCli().then(
    (exitCode) => {
      process.exit(exitCode);
    },
    (err: unknown) => {
      console.error('Fatal:', err);
      process.exit(1);
    },
  );
}

export { analyzeBundlePipeline, cleanupPipelineResult } from './analyze.js';
export type { PipelineOptions, PipelineResult, PipelineProgressEvent, PipelineStepStatus, AIMode } from './analyze.js';

export {
  createTrace,
  startTraceStep,
  completeTraceStep,
  completeTrace,
} from './trace.js';
export type { TraceStep, InvestigationTrace } from './trace.js';

export * from './analyzer.js';
export * from './bundle.js';
export * from './finding.js';
export * from './graph.js';
export * from './kubernetes.js';
export * from './rag.js';

export * from './config.js';
export { CassetteRecorder, cassetteSeedKey, getRecorderMode } from './recorder.js';
export type { RecorderMode, Cassette, CassetteStore } from './recorder.js';
export { summarizeResource, summarizeEvent, summarizeAnalyzer, summarizeHelmRelease } from './summarizer.js';
export { buildChunkIndex } from './chunk-indexer.js';
export type { IndexedChunk } from './chunk-indexer.js';
export { generateChunkContext, contextualizeChunks, buildDocumentContext } from './contextual-retrieval.js';
export type { DocumentContext } from './contextual-retrieval.js';
export { LexicalSearchIndex } from './lexical-search.js';
export type { ScoredChunk as LexicalScoredChunk } from './lexical-search.js';
export { validateAIFindings } from './schemas.js';
export type { AIFinding, AIFindingEvidence } from './schemas.js';
export {
  BASE_SYSTEM_PROMPT,
  SEED_CLUSTERING_SYSTEM_PROMPT,
  buildInvestigationPrompt,
  buildSeedClusteringPrompt,
  resolvePlaybookCategory,
} from './prompts.js';
export type { PlaybookCategory } from './prompts.js';
export { LLMClient } from './llm-client.js';
export type {
  AIFindingResponse,
  InvestigationLLMClient,
  SeedAwareInvestigationLLMClient,
} from './llm-client.js';
export { ReplayableLLMClient, defaultSeedResolver } from './replayable-llm-client.js';
export type { SeedIdentity } from './replayable-llm-client.js';
export { EmbeddingClient } from './embeddings.js';
export type { EmbeddingClientInterface } from './embeddings.js';
export { LocalEmbeddingClient, createEmbeddingClient } from './local-embeddings.js';
export type { LocalBackendType, LocalEmbeddingClientConfig } from './local-embeddings.js';
export { mapChunkBoundariesToTokenPositions, averagePoolSlice, lateChunkEmbed } from './late-chunking.js';
export type { ChunkBoundary, TokenRange, LateChunkEmbeddingClient } from './late-chunking.js';
export { VectorStore, cosineSimilarity } from './vector-store.js';
export type { ScoredChunk } from './vector-store.js';
export { generateHypotheticalDocument, HYDE_SYSTEM_PROMPT } from './hyde.js';
export type { HydeLLMClient } from './hyde.js';
export {
  aggregateAIRunStats,
  estimateLLMCostUsd,
  toAIRunSummary,
  zeroAIRunStats,
} from './telemetry.js';
export type { AICallMetrics, AIRunStats, AIRunSummary } from './telemetry.js';
export { computeRetrievalMetrics, aggregateRetrievalMetrics } from './retrieval-metrics.js';
export type { RetrievalMetrics } from './retrieval-metrics.js';

