import { Command, CommanderError, InvalidArgumentError } from 'commander';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type OutputFormat = 'json' | 'text' | 'summary' | 'markdown' | 'html';

export interface ParsedArgs {
  bundlePath: string;
  outputDir?: string;
  format: OutputFormat;
  verbose: boolean;
  trace: boolean;
  debug: boolean;
  noAi: boolean;
  /** When true, launch the interactive TUI instead of printing to stdout. */
  tui: boolean;
}

// ---------------------------------------------------------------------------
// Validators
// ---------------------------------------------------------------------------

const VALID_FORMATS: OutputFormat[] = ['json', 'text', 'summary', 'markdown', 'html'];

function validateFormat(value: string): OutputFormat {
  if (!VALID_FORMATS.includes(value as OutputFormat)) {
    throw new InvalidArgumentError(
      `Invalid format "${value}". Must be one of: ${VALID_FORMATS.join(', ')}.`,
    );
  }
  return value as OutputFormat;
}

// ---------------------------------------------------------------------------
// parseArgs
// ---------------------------------------------------------------------------

/**
 * Parses command-line arguments using Commander.
 *
 * Uses `exitOverride()` so that `--help`/`--version` and invalid arguments
 * throw a {@link CommanderError} instead of calling `process.exit` directly.
 * The caller (typically the CLI entry point) is responsible for catching
 * these errors and exiting appropriately.
 *
 * @param argv - Raw argument vector. Defaults to `process.argv`.
 *               In tests, pass `['node', 'sbi', 'analyze', '<bundle>', ...]`.
 * @throws {CommanderError} when `--help` or `--version` is requested (code 0)
 *         or when required arguments are missing/invalid (code 1).
 */
export function parseArgs(argv: string[] = process.argv): ParsedArgs {
  let bundlePath = '';
  let capturedOpts: {
    outputDir?: string;
    format?: OutputFormat;
    verbose?: boolean;
    trace?: boolean;
    debug?: boolean;
    /** Commander --no-ai stores the negation under property `ai` */
    ai?: boolean;
    tui?: boolean;
  } = {};

  const program = new Command();

  // Prevent Commander from calling process.exit; throw CommanderError instead
  program.exitOverride();

  program
    .name('sbi')
    .description(
      'Support Bundle Investigator — evidence-backed diagnosis from support bundles',
    )
    .version('0.1.0');

  const analyzeCmd = new Command('analyze');
  analyzeCmd
    .description('Analyze a support bundle .tar.gz archive')
    .argument('<bundle-path>', 'Path to the support bundle .tar.gz file')
    .option(
      '--output-dir <dir>',
      'Directory to write output artifacts (findings.json, report.md, report.html, optional trace.json)',
    )
    .option(
      '--format <format>',
      'Output format: json | text | summary | markdown | html (default: text)',
      validateFormat,
      'text' as OutputFormat,
    )
    .option('--verbose', 'Enable verbose pipeline logging', false)
    .option('--trace', 'Write a JSON trace file to the output directory', false)
    .option('--debug', 'Include debug-oriented provenance fields in machine-readable output', false)
    .option('--no-ai', 'Disable AI features and run in heuristic-only mode')
    .option('--tui', 'Launch interactive terminal UI for investigation results', false)
    .exitOverride()
    .action((bp: string, opts: typeof capturedOpts) => {
      bundlePath = bp;
      capturedOpts = opts;
    });

  program.addCommand(analyzeCmd);
  program.parse(argv);

  if (!bundlePath) {
    // No subcommand was matched — show help and throw
    throw new CommanderError(
      1,
      'commander.missingArgument',
      'Missing required argument: bundle-path. Run `sbi analyze --help` for usage.',
    );
  }

  return {
    bundlePath,
    outputDir: capturedOpts.outputDir,
    format: capturedOpts.format ?? 'text',
    verbose: capturedOpts.verbose ?? false,
    trace: capturedOpts.trace ?? false,
    debug: capturedOpts.debug ?? false,
    // Commander's --no-ai sets `ai` to false; absence means AI is not disabled
    noAi: capturedOpts.ai === false,
    tui: capturedOpts.tui ?? false,
  };
}

/**
 * Re-export so callers can do instance checks without importing commander directly.
 */
export { CommanderError };

import { parseArgs, CommanderError } from './cli.js';
import { analyzeBundlePipeline, cleanupPipelineResult } from '../pipeline/analyze.js';
import { writePipelineResult, writeTraceFile } from './output.js';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface RunCliOptions {
  /**
   * Lazy loader for the TUI module.  Provided only by the CLI binary entry
   * point (`src/cli/run.ts`) where the relative import path to `dist/tui/`
   * is stable.  Omitted when `runCli` is called from the library entry
   * (`src/index.ts`) or from tests.
   */
  loadTUI?: () => Promise<{
    renderTUI: (bundlePath: string, options: Record<string, unknown>) => Promise<void>;
  }>;
}

// ---------------------------------------------------------------------------
// runCli
// ---------------------------------------------------------------------------

/**
 * Runs the SBI CLI for the provided argv vector and returns the intended exit
 * code instead of terminating the process directly.
 *
 * @param argv    - Raw argument vector (defaults to `process.argv`).
 * @param options - Optional dependency-injection options (e.g. TUI loader).
 */
export async function runCli(
  argv: string[] = process.argv,
  options: RunCliOptions = {},
): Promise<number> {
  let args;
  let result: Awaited<ReturnType<typeof analyzeBundlePipeline>> | undefined;

  try {
    args = parseArgs(argv);
  } catch (err) {
    if (err instanceof CommanderError) {
      // exitCode 0 = --help / --version (output already printed by Commander)
      return err.exitCode;
    }

    console.error((err as Error).message);
    return 1;
  }

  // ── TUI mode ─────────────────────────────────────────────────────────────
  if (args.tui) {
    if (!options.loadTUI) {
      console.error('Error: --tui is only supported when running via the sbi CLI binary.');
      return 1;
    }

    try {
      const { renderTUI } = await options.loadTUI();
      await renderTUI(args.bundlePath, {
        outputDir: args.outputDir,
        verbose: args.verbose,
        noAi: args.noAi,
        trace: args.trace,
        debug: args.debug,
      });
      return 0;
    } catch (err) {
      console.error('Error:', (err as Error).message);
      return 1;
    }
  }

  // ── Standard pipeline mode ────────────────────────────────────────────────
  try {
    result = await analyzeBundlePipeline(args.bundlePath, {
      outputDir: args.outputDir,
      verbose: args.verbose,
      trace: args.trace,
      debug: args.debug,
      noAi: args.noAi,
    });

    await writePipelineResult(result, {
      format: args.format,
      outputDir: args.outputDir,
      verbose: args.verbose,
      debug: args.debug,
    });

    if (args.trace && args.outputDir) {
      await writeTraceFile(result.trace, args.outputDir);
    }

    return 0;
  } catch (err) {
    console.error('Error:', (err as Error).message);
    return 1;
  } finally {
    if (result) {
      await cleanupPipelineResult(result);
    }
  }
}

import * as fsp from 'fs/promises';
import * as path from 'path';
import type { BundleProfile } from '../types/index.js';
import type { InvestigationTrace } from '../pipeline/trace.js';
import type { PipelineResult } from '../pipeline/analyze.js';
import {
  buildReport,
  generateJsonReport,
  generateMarkdownReport,
  generateHtmlReport,
  writeJsonReport,
} from '../reporters/index.js';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface OutputOptions {
  format: 'json' | 'text' | 'summary' | 'markdown' | 'html';
  outputDir?: string;
  verbose?: boolean;
  debug?: boolean;
}

// ---------------------------------------------------------------------------
// Console output
// ---------------------------------------------------------------------------

/**
 * Prints a human-readable summary of the bundle profile to stdout.
 */
export function printProfileSummary(profile: BundleProfile): void {
  const { manifest, analyzerCount, logFileCount, resourceCount, eventCount } = profile;

  console.log('');
  console.log('═══════════════════════════════════════════════════════');
  console.log('  Support Bundle Profile');
  console.log('═══════════════════════════════════════════════════════');
  console.log(`  Bundle:       ${manifest.bundlePath}`);
  console.log(`  Files:        ${manifest.files.length}`);
  console.log(`  Analyzers:    ${analyzerCount}`);
  console.log(`  Resources:    ${resourceCount}`);
  console.log(`  Events:       ${eventCount}`);
  console.log(`  Log files:    ${logFileCount}`);
  console.log('');

  if (profile.namespaces.length > 0) {
    console.log(`  Namespaces:   ${profile.namespaces.join(', ')}`);
  }

  if (profile.workloads.length > 0) {
    console.log('');
    console.log('  Workloads:');
    for (const wl of profile.workloads) {
      console.log(`    - [${wl.kind}] ${wl.namespace}/${wl.name}`);
    }
  }

  if (profile.coverageGaps.length > 0) {
    console.log('');
    console.log('  Coverage gaps:');
    for (const gap of profile.coverageGaps) {
      console.log(`    ⚠  ${gap}`);
    }
  }

  console.log('═══════════════════════════════════════════════════════');
  console.log('');
}

// ---------------------------------------------------------------------------
// File output
// ---------------------------------------------------------------------------

/**
 * Writes the investigation trace to a JSON file in `outputDir`.
 */
export async function writeTraceFile(
  trace: InvestigationTrace,
  outputDir: string,
): Promise<void> {
  await fsp.mkdir(outputDir, { recursive: true });
  const traceFile = path.join(outputDir, 'trace.json');
  await fsp.writeFile(traceFile, JSON.stringify(trace, null, 2), 'utf-8');
}

/**
 * Prints a text summary of analysis results to stdout.
 *
 * @deprecated Prefer `writePipelineResult` which now uses the Markdown reporter.
 *             Kept for backward-compatible re-exports.
 */
export function printTextSummary(result: PipelineResult): void {
  printProfileSummary(result.profile);

  const errors = result.analyzerResults.filter((r) => r.isFail);
  const warns = result.analyzerResults.filter((r) => r.isWarn);

  if (errors.length > 0) {
    console.log('  ❌  Analyzer Errors:');
    for (const e of errors) {
      console.log(`    [${e.name}] ${e.title}`);
      if (e.message) console.log(`      ${e.message}`);
    }
    console.log('');
  }

  if (warns.length > 0) {
    console.log('  ⚠   Analyzer Warnings:');
    for (const w of warns) {
      console.log(`    [${w.name}] ${w.title}`);
      if (w.message) console.log(`      ${w.message}`);
    }
    console.log('');
  }
}

/**
 * Writes the pipeline result to disk or prints to stdout depending on the
 * output options.
 *
 * When `outputDir` is set, always writes all three report files:
 *   - `findings.json`  — full structured report (via JSON reporter)
 *   - `report.md`      — human-readable Markdown report
 *   - `report.html`    — self-contained HTML report with embedded CSS
 *
 * When `outputDir` is not set, format controls stdout output:
 *   - `json`           — prints full JSON report to stdout
 *   - `text`           — prints Markdown report to stdout
 *   - `markdown`       — prints Markdown report to stdout
 *   - `html`           — prints HTML report to stdout
 *   - `summary`        — prints bundle profile summary to stdout
 */
export async function writePipelineResult(
  result: PipelineResult,
  options: OutputOptions,
): Promise<void> {
  const { format, outputDir } = options;
  const includeProvenance = options.debug === true || result.debug === true;

  if (outputDir) {
    // Always write all three report files when an output directory is provided.
    const resolvedDir = path.resolve(outputDir);
    await fsp.mkdir(resolvedDir, { recursive: true });

    const report = buildReport(result);

    await writeJsonReport(report, resolvedDir, { includeProvenance });

    const mdPath = path.join(resolvedDir, 'report.md');
    await fsp.writeFile(mdPath, generateMarkdownReport(report), 'utf-8');

    const htmlPath = path.join(resolvedDir, 'report.html');
    await fsp.writeFile(htmlPath, generateHtmlReport(report), 'utf-8');

    console.log(`Reports written to ${resolvedDir}: findings.json, report.md, report.html`);
    return;
  }

  // No outputDir — print to stdout based on format.
  if (format === 'summary') {
    printProfileSummary(result.profile);
    return;
  }

  const report = buildReport(result);

  if (format === 'json') {
    console.log(generateJsonReport(report, { includeProvenance }));
  } else if (format === 'html') {
    console.log(generateHtmlReport(report));
  } else {
    // 'text' | 'markdown'
    console.log(generateMarkdownReport(report));
  }
}

import { describe, it, expect } from 'vitest';
