import type { ArtifactCategory, ArtifactEntry } from '../types/index.js';

/**
 * Returns the index of `segment` within `segments`, or -1 if not found.
 * Matching is case-sensitive and exact (no wildcards).
 */
function indexOf(segments: string[], segment: string): number {
  return segments.indexOf(segment);
}

/**
 * Classifies a single ArtifactEntry by inspecting its relativePath.
 *
 * Classification rules (evaluated in priority order):
 * - filename is "version.yaml"                        -> 'cluster-info'
 * - path contains "cluster-info" segment              -> 'cluster-info'
 * - filename is "analysis.json"                       -> 'analyzer'
 * - path contains "analyzers" segment                 -> 'analyzer'
 * - path under cluster-resources/pods/logs/           -> 'log'
 * - path under cluster-resources/events/              -> 'event'
 * - path contains "cluster-resources" segment         -> 'kubernetes-resource'
 * - path contains "logs" segment                      -> 'log'
 * - path contains "helm" segment                      -> 'helm-release'
 * - (anything else)                                   -> 'unknown'
 *
 * The path is split on '/' so that a bundle root directory prefix (e.g.
 * "my-bundle/analyzers/output.json") is handled transparently.
 */
export function classifyArtifact(entry: ArtifactEntry): ArtifactCategory {
  const { relativePath } = entry;
  const segments = relativePath.split('/');
  const filename = segments[segments.length - 1] ?? '';

  // version.yaml anywhere in the path → cluster-info
  if (filename === 'version.yaml') {
    return 'cluster-info';
  }

  // cluster-info directory segment → cluster-info
  if (indexOf(segments, 'cluster-info') >= 0) {
    return 'cluster-info';
  }

  // analysis.json at any level → analyzer (real Troubleshoot bundles use this
  // filename at the bundle root instead of an analyzers/ directory)
  if (filename === 'analysis.json') {
    return 'analyzer';
  }

  // analyzers directory segment → analyzer (legacy / custom bundles)
  if (indexOf(segments, 'analyzers') >= 0) {
    return 'analyzer';
  }

  // cluster-resources segment — check sub-kind before returning kubernetes-resource
  const crIdx = indexOf(segments, 'cluster-resources');
  if (crIdx >= 0) {
    const subKind = segments[crIdx + 1];

    // Pod logs live under cluster-resources/pods/logs/ — classify as log
    // *before* the generic kubernetes-resource fallback
    if (subKind === 'pods') {
      const nextSegment = segments[crIdx + 2];
      if (nextSegment === 'logs') {
        return 'log';
      }
    }

    if (subKind === 'events') {
      return 'event';
    }
    return 'kubernetes-resource';
  }

  // logs directory segment → log
  if (indexOf(segments, 'logs') >= 0) {
    return 'log';
  }

  // helm directory segment → helm-release
  if (indexOf(segments, 'helm') >= 0) {
    return 'helm-release';
  }

  return 'unknown';
}

import * as fsp from 'fs/promises';
import * as path from 'path';
import * as yaml from 'js-yaml';
import type { K8sResource } from '../types/index.js';

// ---------------------------------------------------------------------------
// Type guards
// ---------------------------------------------------------------------------

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Returns true if the parsed object has the minimum fields required to be
 * treated as a K8sResource (apiVersion + kind are strings).
 */
function isValidResource(doc: unknown): doc is K8sResource {
  if (!isRecord(doc)) return false;
  return typeof doc['apiVersion'] === 'string' && typeof doc['kind'] === 'string';
}

// ---------------------------------------------------------------------------
// List unwrapping
// ---------------------------------------------------------------------------

/**
 * If the resource is a *List kind (e.g. PodList, DeploymentList) that
 * contains an `items` array, returns the individual items.  Otherwise
 * returns a single-element array containing the resource itself.
 */
function expandListResource(resource: K8sResource): K8sResource[] {
  if (!resource.kind.endsWith('List')) {
    return [resource];
  }

  const raw = resource as unknown as Record<string, unknown>;
  const items = raw['items'];

  if (!Array.isArray(items)) {
    return [];
  }

  return items.filter(isValidResource);
}

// ---------------------------------------------------------------------------
// parseResourceYaml
// ---------------------------------------------------------------------------

/**
 * Parses a YAML string (possibly containing multiple `---`-separated
 * documents) and returns all valid K8sResource objects found.
 *
 * Malformed documents are skipped with a warning so that a single bad
 * document does not abort the parse of the remaining content.
 */
export function parseResourceYaml(content: string): K8sResource[] {
  const results: K8sResource[] = [];

  // Split on YAML document separators so each document can be tried
  // independently — this way a single malformed document doesn't abort
  // the entire file.
  const rawDocuments = content.split(/^---\s*$/m);

  for (const rawDoc of rawDocuments) {
    const trimmed = rawDoc.trim();
    if (!trimmed) continue;

    let doc: unknown;

    try {
      doc = yaml.load(trimmed);
    } catch (err) {
      console.warn(
        `[k8s-resource-parser] Skipping malformed YAML document: ${(err as Error).message}`,
      );
      continue;
    }

    if (doc === null || doc === undefined) continue;

    if (!isValidResource(doc)) {
      console.warn(
        '[k8s-resource-parser] Skipping document — missing required apiVersion or kind fields',
      );
      continue;
    }

    results.push(...expandListResource(doc));
  }

  return results;
}

// ---------------------------------------------------------------------------
// parseResourceJson
// ---------------------------------------------------------------------------

/**
 * Parses a JSON string that represents a single K8sResource (or a *List
 * kind whose `items` are unwrapped) and returns a K8sResource[].
 *
 * On parse or validation failure a warning is logged and an empty array
 * is returned.
 */
export function parseResourceJson(content: string): K8sResource[] {
  let parsed: unknown;

  try {
    parsed = JSON.parse(content);
  } catch (err) {
    console.warn(
      `[k8s-resource-parser] Failed to parse resource JSON: ${(err as Error).message}`,
    );
    return [];
  }

  if (!isValidResource(parsed)) {
    console.warn(
      '[k8s-resource-parser] JSON does not represent a valid K8sResource — missing apiVersion or kind',
    );
    return [];
  }

  return expandListResource(parsed);
}

// ---------------------------------------------------------------------------
// parseResourceFile
// ---------------------------------------------------------------------------

/**
 * Reads a Kubernetes resource file from disk and parses it.
 *
 * The parser is selected based on the file extension:
 * - `.json` → {@link parseResourceJson}
 * - everything else (`.yaml`, `.yml`, unknown) → {@link parseResourceYaml}
 *
 * On I/O or parse errors a warning is logged and an empty array is returned
 * so that the pipeline can continue processing other files.
 */
export async function parseResourceFile(filePath: string): Promise<K8sResource[]> {
  let content: string;

  try {
    content = await fsp.readFile(filePath, 'utf-8');
  } catch (err) {
    console.warn(
      `[k8s-resource-parser] Could not read resource file "${filePath}": ${(err as Error).message}`,
    );
    return [];
  }

  const ext = path.extname(filePath).toLowerCase();

  if (ext === '.json') {
    return parseResourceJson(content);
  }

  return parseResourceYaml(content);
}

import * as fsp from 'fs/promises';
import * as path from 'path';
import * as yaml from 'js-yaml';
import type { K8sEvent } from '../types/index.js';

// ---------------------------------------------------------------------------
// Type guards / helpers
// ---------------------------------------------------------------------------

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function getString(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

function getOptionalString(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

function getOptionalNumber(value: unknown): number | undefined {
  return typeof value === 'number' ? value : undefined;
}

function hasRequiredInvolvedObjectFields(value: unknown): value is Record<string, unknown> {
  if (!isRecord(value)) return false;

  return (
    typeof value['kind'] === 'string' &&
    value['kind'].trim().length > 0 &&
    typeof value['name'] === 'string' &&
    value['name'].trim().length > 0
  );
}

/**
 * Maps a raw (unknown) object to a K8sEvent. Missing or malformed fields
 * fall back to safe defaults so the rest of the pipeline is unaffected.
 *
 * Completely malformed records are skipped by returning `null`.
 */
function mapToEvent(raw: unknown): K8sEvent | null {
  if (!isRecord(raw)) return null;

  const involvedRaw = raw['involvedObject'];
  if (!hasRequiredInvolvedObjectFields(involvedRaw)) {
    return null;
  }

  const involvedObject = {
    kind: getString(involvedRaw['kind']),
    name: getString(involvedRaw['name']),
    namespace: getOptionalString(involvedRaw['namespace']),
  };

  return {
    type: getString(raw['type']),
    reason: getString(raw['reason']),
    message: getString(raw['message']),
    involvedObject,
    firstTimestamp: getOptionalString(raw['firstTimestamp']),
    lastTimestamp: getOptionalString(raw['lastTimestamp']),
    count: getOptionalNumber(raw['count']),
  };
}

/**
 * Normalises a parsed JSON/YAML value into an array of raw event objects.
 *
 * Accepts:
 * - A plain array of event objects
 * - An EventList wrapper `{ kind: 'EventList', items: [...] }`
 * - A single Event object `{ kind: 'Event', ... }`
 */
function normaliseToArray(parsed: unknown): unknown[] {
  if (Array.isArray(parsed)) {
    return parsed;
  }

  if (!isRecord(parsed)) return [];

  const kind = parsed['kind'];

  if (typeof kind === 'string' && kind.endsWith('List')) {
    const items = parsed['items'];
    if (Array.isArray(items)) {
      return items;
    }
    return [];
  }

  // Single document — wrap in array
  return [parsed];
}

// ---------------------------------------------------------------------------
// parseEventsJson
// ---------------------------------------------------------------------------

/**
 * Parses a JSON string into an array of {@link K8sEvent} objects.
 *
 * Accepts two formats:
 * - A raw JSON array: `[{ "type": "Warning", ... }, ...]`
 * - An EventList wrapper: `{ "kind": "EventList", "items": [...] }`
 *
 * On any parse or validation error a warning is logged and an empty array
 * is returned.
 */
export function parseEventsJson(content: string): K8sEvent[] {
  if (!content.trim()) return [];

  let parsed: unknown;

  try {
    parsed = JSON.parse(content);
  } catch (err) {
    console.warn(
      `[event-parser] Failed to parse events JSON: ${(err as Error).message}`,
    );
    return [];
  }

  const items = normaliseToArray(parsed);
  const events: K8sEvent[] = [];

  for (const item of items) {
    const event = mapToEvent(item);
    if (event) {
      events.push(event);
    }
  }

  return events;
}

// ---------------------------------------------------------------------------
// parseEventsYaml
// ---------------------------------------------------------------------------

/**
 * Parses a YAML string into an array of {@link K8sEvent} objects.
 *
 * Accepts:
 * - A single Event document
 * - An EventList document: `kind: EventList` with `items:` array
 * - Multiple `---`-separated YAML documents containing either format
 *
 * Malformed YAML documents are skipped with a warning so that a single bad
 * document does not abort parsing of the remaining content.
 */
export function parseEventsYaml(content: string): K8sEvent[] {
  const trimmed = content.trim();
  if (!trimmed) return [];

  const documents = trimmed.split(/^---\s*$/m);
  const events: K8sEvent[] = [];

  for (const rawDocument of documents) {
    const docText = rawDocument.trim();
    if (!docText) continue;

    let parsed: unknown;

    try {
      parsed = yaml.load(docText);
    } catch (err) {
      console.warn(
        `[event-parser] Failed to parse events YAML: ${(err as Error).message}`,
      );
      continue;
    }

    if (parsed === null || parsed === undefined) continue;

    const items = normaliseToArray(parsed);

    for (const item of items) {
      const event = mapToEvent(item);
      if (event) {
        events.push(event);
      }
    }
  }

  return events;
}

