  [/\bERROR\b/i, 'error'],
  // Warn
  [/\blevel\s*=\s*warn(ing)?\b/i, 'warning'],
  [/\[WARN(ING)?\]/i, 'warning'],
  [/\bWARN(ING)?\b/i, 'warning'],
  // Info
  [/\blevel\s*=\s*info\b/i, 'info'],
  [/\[INFO\]/i, 'info'],
