function makeSensitiveChunk(): IndexedChunk {
  return {
    id: 'chunk:sensitive:0',
    artifactId: 'cluster-resources/configmaps/default/app-config.yaml',
    content: `api-key: ${SECRET_CANARY}\npassword=${PASSWORD_CANARY}`,
    startLine: 1,
