    confidence: 0.75,
    affectedComponents: ['web', 'api'],
    reasoningSummary: 'A database hostname misconfiguration is causing DNS lookup failures.',
    evidence: [
      {
        path: 'logs/app/current.log',
        note: 'lookup db.internal: no such host',
