    recommendedAction: 'Update the DB_HOST environment variable to the correct hostname.',
    missingEvidence: ['Kubernetes events for pod app-pod'],
    ...overrides,
  };
}

function makeCriticalFinding(): Finding {
  return makeFinding({
    id: 'finding:test:critical',
