    analyzerCount: 1,
    resourceCount: 2,
    eventCount: 1,
    logFileCount: 1,
    namespaces: ['default'],
    workloads: [],
    coverageGaps: [],
    artifactsByCategory: emptyByCategory,
  };
}

function makePipelineResult(findings: Finding[] = []): PipelineResult {
  return {
    profile: makeMinimalProfile(),
    analyzerResults: [],
    resources: [],
    events: [],
    logs: [],
    findings,
    findingTree: [],
    graph: {
      nodes: new Map(),
      edges: [],
